const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard1dDilatedStridedCustomTilingData tiling;

    // Inputs:
    // x: [N, IC, L]
    // w: [OC, IC, K]
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);

    uint32_t N  = static_cast<uint32_t>(GetDim(xShape, 0));
    uint32_t IC = static_cast<uint32_t>(GetDim(xShape, 1));
    uint32_t L  = static_cast<uint32_t>(GetDim(xShape, 2));

    uint32_t OC = static_cast<uint32_t>(GetDim(wShape, 0));
    uint32_t K  = static_cast<uint32_t>(GetDim(wShape, 2));

    // Attributes: stride, dilation, hasBias are passed from attrs
    const gert::RuntimeAttrs* attrs = context->GetAttrs();
    uint32_t stride   = *(attrs->GetAttrPointer<uint32_t>(0));
    uint32_t dilation = *(attrs->GetAttrPointer<uint32_t>(1));
    uint32_t hasBias  = *(attrs->GetAttrPointer<uint32_t>(2));

    // Output length
    uint32_t Lout = (L >= (dilation * (K - 1) + 1))
        ? (static_cast<uint32_t>((static_cast<int64_t>(L) - static_cast<int64_t>(dilation) * (static_cast<int64_t>(K) - 1) - 1) / static_cast<int64_t>(stride)) + 1)
        : 0;

    context->SetBlockDim(BLOCK_DIM);

    uint32_t totalLength = N * OC * Lout;

    tiling.set_totalLength(totalLength);
    tiling.set_tileNum(TILE_NUM);
    tiling.set_N(N);
    tiling.set_IC(IC);
    tiling.set_OC(OC);
    tiling.set_L(L);
    tiling.set_K(K);
    tiling.set_stride(stride);
    tiling.set_dilation(dilation);
    tiling.set_Lout(Lout);
    tiling.set_hasBias(hasBias);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    context->SetTilingKey(1);
    return ge::GRAPH_SUCCESS;
}
